def from_pov(self, from_node):
    result = self._reorient(from_node)
    if result is None:
        raise ValueError("Tree could not be reoriented")
    return result

def _reorient(self, node):
    if self.label == node:
        # copy the children
        return Tree(self.label, [Tree(c.label, list(c.children)) for c in self.children])
    for i, child in enumerate(self.children):
        result = child._reorient(node)
        if result is not None:
            # rebuild self with that child replaced by result, and result gets the old self as a child
            children = [Tree(c.label, list(c.children)) for j, c in enumerate(self.children) if j != i]
            new_result = result
            new_result.children.append(Tree(self.label, children))
